fn reset_clause_scalar_occurrences(
    out: &ParseOutput,
    occurrences: &mut HashMap<(usize, usize), u8>,
) {
    let Some(clause) = out.cmd.clause.as_ref() else {
        return;
    };
    let names = clause
        .flags
        .iter()
        .map(|flag| flag.name.as_str())
        .collect::<HashSet<_>>();
    let pointers = unique_flags(out.available_flags.values())
        .filter(|flag| names.contains(flag.name.as_str()))
        .map(|flag| Arc::as_ptr(flag) as usize)
        .collect::<HashSet<_>>();
    occurrences.retain(|(flag, _), _| !pointers.contains(flag));
}

fn cursor_skip_sigils(cmd: &SpecCommand, mut idx: usize) -> usize {
    while active_args(cmd)
        .get(idx)
        .is_some_and(|arg| arg.sigil.is_some())
    {
        idx += 1;
    }
    idx
}

fn active_args(cmd: &SpecCommand) -> &[SpecArg] {
    cmd.clause
        .as_ref()
        .map(|clause| clause.args.as_slice())
        .unwrap_or(cmd.args.as_slice())
}

fn match_sigil_arg<'a>(
    cmd: &'a SpecCommand,
    word: &'a str,
) -> Option<(&'a SpecArg, &'a str, &'a str)> {
    cmd.args
        .iter()
        .filter_map(|arg| {
            let sigil = arg.sigil.as_deref()?;
            let value = word.strip_prefix(sigil)?;
            Some((arg, sigil, value))
        })
        .max_by_key(|(_, sigil, _)| sigil.len())
}

fn match_sigil_arg_chain<'a>(
    cmds: &'a [SpecCommand],
    word: &'a str,
) -> Option<(&'a SpecArg, &'a str, &'a str)> {
    cmds.iter()
        .filter_map(|cmd| match_sigil_arg(cmd, word))
        .max_by_key(|(_, sigil, _)| sigil.len())
}

