use crate::error::Result;
use crate::kdl::{KdlDocument, KdlEntry, KdlNode};
use crate::spec::context::ParsingContext;
use crate::spec::helpers::{string_entry, NodeHelper};
use crate::{SpecArg, SpecFlag};
use serde::Serialize;
use std::collections::HashSet;

/// A repeatable group of scoped flags and positional arguments.
#[derive(Debug, Default, Clone, Serialize)]
#[non_exhaustive]
pub struct SpecClause {
    pub name: String,
    pub separator: Option<String>,
    pub flags: Vec<SpecFlag>,
    pub args: Vec<SpecArg>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub help: Option<String>,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub help_long: Option<String>,
    pub usage: String,
}

impl SpecClause {
    pub(crate) fn conflicting_flag_spelling(&self, command_flags: &[SpecFlag]) -> Option<String> {
        fn spellings(flag: &SpecFlag) -> impl Iterator<Item = String> + '_ {
            flag.long
                .iter()
                .chain(&flag.hidden_aliases)
                .map(|name| format!("--{name}"))
                .chain(
                    flag.short
                        .iter()
                        .chain(&flag.hidden_short_aliases)
                        .map(|name| format!("-{name}")),
                )
                .chain(flag.negate.iter().cloned())
        }

        let mut seen = command_flags
            .iter()
            .flat_map(spellings)
            .collect::<HashSet<_>>();
        self.flags
            .iter()
            .flat_map(spellings)
            .find(|spelling| !seen.insert(spelling.clone()))
    }

    pub(crate) fn parse(ctx: &ParsingContext, node: &NodeHelper) -> Result<Self> {
        let mut clause = Self {
            name: node.arg(0)?.ensure_string()?,
            ..Self::default()
        };
        for (key, value) in node.props() {
            match key {
                "separator" => clause.separator = Some(value.ensure_string()?),
                "help" => clause.help = Some(value.ensure_string()?),
                "help_long" | "long_help" => clause.help_long = Some(value.ensure_string()?),
                key => bail_parse!(ctx, value.entry.span(), "unsupported clause key {key}"),
            }
        }
        for child in node.children() {
            match child.name() {
                "arg" => clause.args.push(SpecArg::parse(ctx, &child)?),
                "flag" => clause.flags.push(SpecFlag::parse(ctx, &child)?),
                key => bail_parse!(
                    ctx,
                    child.node.name().span(),
                    "unsupported clause child {key}"
                ),
            }
        }
        if clause.name.is_empty() {
            bail_parse!(ctx, node.span(), "a clause needs a name");
        }
        if clause.separator.as_ref().is_some_and(String::is_empty) {
            bail_parse!(ctx, node.span(), "clause separator cannot be empty");
        }
        if clause
            .separator
            .as_ref()
            .is_some_and(|separator| separator.starts_with('-'))
        {
            bail_parse!(ctx, node.span(), "clause separator cannot start with `-`");
        }
        if clause.args.is_empty() {
            bail_parse!(
                ctx,
                node.span(),
                "clause {} needs at least one argument",
                clause.name
            );
        }
        if clause.separator.is_none()
            && (clause.args.len() != 1 || !clause.args[0].required || clause.args[0].var)
        {
            bail_parse!(
                ctx,
                node.span(),
                "an implicit clause needs exactly one required, non-variadic positional argument"
            );
        }
        clause.usage = clause.usage();
        Ok(clause)
    }

    pub fn usage(&self) -> String {
        let inner = self
            .args
            .iter()
            .map(SpecArg::usage)
            .collect::<Vec<_>>()
            .join(" ");
        match &self.separator {
            Some(separator) => format!("[{inner} [{separator} {inner}]…]"),
            None => {
                let Some(arg) = self.args.first() else {
                    return String::new();
                };
                let mut arg = arg.clone();
                arg.required = false;
                arg.var = true;
                arg.usage()
            }
            if let Some(sigil) = &arg.sigil {
                if let Some(existing) = sigils
                    .iter()
                    .find(|existing| existing.starts_with(sigil) || sigil.starts_with(**existing))
                {
                    bail_parse!(
                        ctx,
                        node.node.name().span(),
                        "argument sigils must not overlap: {existing:?} and {sigil:?}"
                    );
                }
                sigils.push(sigil);
            }
        }
        if let Some(clause) = &cmd.clause {
            if !cmd.args.is_empty() {
                bail_parse!(
                    ctx,
                    node.span(),
                    "a command cannot declare both top-level arguments and a clause"
                );
            }
            if cmd.restart_token.is_some() {
                bail_parse!(
                    ctx,
                    node.span(),
                    "a command cannot declare both restart_token and a clause"
                );
            }
            if clause.args.iter().any(|arg| arg.sigil.is_some()) {
                bail_parse!(
                    ctx,
                    node.span(),
                    "sigil arguments are not supported inside clauses"
                );
            }
            if let Some(spelling) = clause.conflicting_flag_spelling(&cmd.flags) {
                bail_parse!(
                    ctx,
                    node.span(),
                    "clause flag spelling {spelling:?} conflicts with another flag on this command"
    }

    #[test]
    fn an_exclusive_flag_conflicts_with_clause_arguments() {
        let spec: Spec = r#"name "ex"
bin "ex"
flag "--dump" exclusive=#true
clause "tasks" separator=":::" {
  arg "<task>"
}
"#
        .parse()
        .unwrap();

        let err = parse(&spec, &input(&["ex", "--dump", "lint"])).unwrap_err();
        assert!(err.to_string().contains("on its own"), "{err}");
    }

    #[test]
    fn a_partial_parse_reports_the_next_implicit_clause_argument() {
        let spec: Spec = r#"name "ex"
bin "ex"
clause "tools" {
  arg "<tool@version>"
}
"#
        .parse()
        .unwrap();

        let parsed = parse_partial(&spec, &input(&["ex"])).unwrap();

        assert_eq!(
            parsed.next_arg.as_ref().map(|arg| arg.name.as_str()),
            Some("tool@version")
        );
    }

    #[test]
    fn an_exclusive_flag_is_not_disturbed_by_a_default() {
        // Only what was supplied counts, as `conflicts` reads it. A default counting as
        // company would make an exclusive flag unusable on any command that has one.
        let spec: Spec = "name \"ex\"\nbin \"ex\"\nflag \"--dump\" exclusive=#true\nflag \"--jobs <n>\" default=\"4\"\n"
            .parse()
            .unwrap();

        parse(&spec, &input(&["ex", "--dump"])).expect("a default is nobody saying anything");

